import { Component } from '@angular/core';
import { Prodavnica } from '../models/prodavnica';
import { Artikal } from '../models/artikal';
import { ActivatedRoute } from '@angular/router';
import { ProdavnicaService } from '../prodavnica.service';
import { KorisnikService } from '../korisnik.service';
import jwt_decode from 'jwt-decode';
import { RecenzijaService } from '../recenzija.service';
import { Review } from '../models/review';

declare var google: any;

@Component({
  selector: 'app-prodavac',
  templateUrl: './prodavac.component.html',
  styleUrls: ['./prodavac.component.css']
})
export class ProdavacComponent {
  prodavnica: Prodavnica = {} as Prodavnica;
  artikliProdavnice: Artikal[] = [];
  filteredArtikli: Artikal[] = [];
  kategorije: string[] = ['haljina', 'jakna', 'majica', 'farmerice', 'pantalone'];

  userId: string = '';

  recenzije: any[] = [];
  currentReviewIndex: number = 0;
  reviewsToShow: Review[] = [];

  constructor(
    private route: ActivatedRoute,
    private prodavnicaService: ProdavnicaService,
    private korisnikService: KorisnikService,
    private recenzijaService: RecenzijaService
  ) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decoded: any = jwt_decode(token);
      this.userId = decoded.id;
    }

    const storeId = this.route.snapshot.paramMap.get('id');
    if (storeId) {
      this.prodavnicaService.dohvatiProdavnicuSaArtiklima(storeId).subscribe(
        (response) => {
          this.prodavnica = response.prodavnica;
          this.artikliProdavnice = this.prodavnica.artikli;
          this.filteredArtikli = this.artikliProdavnice;

          this.loadMap(this.prodavnica.adresa);
          this.dohvatiRecenzije(storeId);
        },
        (error) => console.error('Greška pri dohvatanju prodavnice', error)
      );
    }
  }

  // Get recenzije
  dohvatiRecenzije(storeId: string): void {
    this.recenzijaService.dohvatiRecenzije(storeId).subscribe(
      (response: any[]) => {
        this.recenzije = response.map((rec) => ({
          ...rec,
          kupac: rec.kupac ? { ime: rec.kupac.ime } : { ime: 'Nepoznato' }
        }));
        this.updateReviewsToShow();
      },
      (error) => console.error('Greška pri dohvatanju recenzija', error)
    );
  }

  loadMap(address: string) {
    const geocoder = new google.maps.Geocoder();
    geocoder.geocode({ address }, (results: any[], status: string) => {
      if (status === 'OK' && results[0]) {
        const location = results[0].geometry.location;

        const map = new google.maps.Map(document.getElementById('map'), {
          zoom: 14,
          center: location
        });

        new google.maps.Marker({ position: location, map });
      }
    });
  }

  addToFavorites(): void {
    this.korisnikService
      .addToFavorites(this.userId, this.prodavnica._id)
      .subscribe(
        () => console.log('Prodavnica dodata u omiljene'),
        (error) => console.error('Greška pri dodavanju u omiljene', error)
      );
  }

  getStoreProfileImage(image: string | undefined): string {
    if (!image) return 'assets/no-image.png';
    return `http://localhost:4000/${image}`;
  }

  // ⭐ ISPRAVLJENA FUNKCIJA → radi sa string | string[] | undefined
  getProductImage(image: string | string[] | undefined): string {
    if (!image) return 'assets/no-image.png';

    const path =
      Array.isArray(image) && image.length > 0 ? image[0] : (image as string);

    if (!path) return 'assets/no-image.png';

    return `http://localhost:4000/${path}`;
  }

  setCategoryFilter(category: string): void {
    this.filteredArtikli =
      category === ''
        ? this.artikliProdavnice
        : this.artikliProdavnice.filter((a) => a.tip === category);
  }

  updateReviewsToShow(): void {
    this.reviewsToShow = this.recenzije.slice(
      this.currentReviewIndex,
      this.currentReviewIndex + 2
    );
  }

  previousReview(): void {
    if (this.currentReviewIndex > 0) {
      this.currentReviewIndex -= 2;
      this.updateReviewsToShow();
    }
  }

  nextReview(): void {
    if (this.currentReviewIndex < this.recenzije.length - 2) {
      this.currentReviewIndex += 2;
      this.updateReviewsToShow();
    }
  }
}
<div class="store-profile-page">
  <!-- Gornji deo stranice -->
  <div class="upper-section">
    <!-- Leva strana - Podaci o prodavnici -->
    <div class="store-info">
      <div class="store-header">
        <h2>{{ prodavnica.ime }}</h2>
        <img [src]="getStoreProfileImage(prodavnica.slika)" alt="Slika prodavnice" class="profile-img">
      </div>

      <div class="store-description">
        <p><strong>Opis:</strong> {{ prodavnica.opis }}</p>
        <p><strong>Adresa:</strong> {{ prodavnica.adresa }}</p>
        <p><strong>RadnoVreme:</strong> {{ prodavnica.radnoVreme }}</p>
        <p><strong>kontaktInfo:</strong> {{ prodavnica.kontaktInfo }}</p>

        <button class="add-to-favorites-btn" (click)="addToFavorites()">Dodaj u omiljene prodavnice</button>
      </div>
    </div>
     <div class="reviews-section">
    <h3>Recenzije prodavnice</h3>
    <div class="carousel">
      <button class="carousel-control left" (click)="previousReview()" [disabled]="currentReviewIndex === 0">&#10094;</button>

      <div class="carousel-container">
        <div *ngFor="let review of recenzije; let i = index" [class.active]="i === currentReviewIndex" class="review-card">
          <div class="review-header">
            <div class="stars">
              <ng-container *ngFor="let star of [1, 2, 3, 4, 5]">
                <span class="star" [class.filled]="star <= review.ocena">&#9733;</span>
              </ng-container>
            </div>
            <p class="review-author">{{ review.kupac.ime }}</p>
          </div>
          <p class="review-comment">{{ review.komentar }}</p>
        </div>
      </div>

      <button class="carousel-control right" (click)="nextReview()" [disabled]="currentReviewIndex === recenzije.length - 1">&#10095;</button>
    </div>
  </div>



    <!-- Desna strana - Lokacija prodavnice na mapi -->
    <div class="store-location">
      <h3>Lokacija prodavnice</h3>
      <div id="map" class="google-map"></div>
    </div>
  </div>


  <!-- Donji deo stranice - Proizvodi iz prodavnice -->
  <div class="related-products">
    <h3>Proizvodi iz prodavnice {{ prodavnica.ime }}</h3>

    <!-- Filter za kategorije -->
    <div class="category-filters">
      <a href="javascript:void(0)" *ngFor="let category of kategorije" (click)="setCategoryFilter(category)">
        {{ category }}
      </a>
      <a href="javascript:void(0)" (click)="setCategoryFilter('')">Svi proizvodi</a>
    </div>

    <!-- Scrollable container -->
    <div class="artikli-container-wrapper">
      <div class="artikli-container" #artikliContainer>
        <div class="artikal-card" *ngFor="let artikal of filteredArtikli" [routerLink]="['/artikal', artikal._id]">
          <img [src]="getProductImage(artikal.slike)" alt="Slika artikla" class="artikal-image" />
          <div class="artikal-info">
            <p>{{ artikal.tip }}</p>
            <p>{{ artikal.cena }} din</p>
          </div>
        </div>
      </div>
    </div>
  </div>

</div>
